# deploy_cube.ps1: deploys and processes the Analysis Services database FlightCube (Plan 2, Task 5b).
# Windows PowerShell 5.1. Runs ssas\FlightCube.xmla (generated by tools\build_cube_xmla.py) on the
# Analysis Services instance DEV, then a Process Full of the database FlightCube.
#
# Usage (repo root):
#   python tools\build_cube_xmla.py                       # regenerate ssas\FlightCube.xmla
#   powershell -File tools\deploy_cube.ps1 -Smoke         # deploy + process + smoke query
#   powershell -File tools\deploy_cube.ps1 -SmokeOnly     # smoke query only (cube already processed)
# Exit code 0 = success, 1 = any error (the XMLA response is checked for <Error>/<Exception>,
# because Invoke-ASCmd does not always raise on a failed command).
#
# It only creates/overwrites/processes the database FlightCube; nothing else on the server.
param(
    [switch]$Smoke,
    [switch]$SmokeOnly,
    [string]$Instance = 'DEV',
    [string]$Xmla = (Join-Path (Split-Path -Parent $PSScriptRoot) 'ssas\FlightCube.xmla')
)
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

$ModuleRoot = Join-Path $env:USERPROFILE 'Documents\WindowsPowerShell\Modules\SqlServer'
$Database = 'FlightCube'

function Say([string]$msg) { [Console]::Out.WriteLine($msg) }   # not part of function return values

function Fail([string]$msg) {
    Say "ERROR: $msg"
    exit 1
}

function Import-SqlServerModule {
    # By name first (any SqlServer version on PSModulePath); then the newest per-user install under
    # Documents\WindowsPowerShell\Modules (that folder is missing from PSModulePath in some shells).
    try { Import-Module SqlServer -DisableNameChecking -ErrorAction Stop; return } catch { }
    $cand = @(Get-ChildItem -Path $ModuleRoot -Filter 'SqlServer.psd1' -Recurse -ErrorAction SilentlyContinue |
              Sort-Object { [version]$_.Directory.Name } -Descending)
    if ($cand.Count -eq 0) { Fail "SqlServer module not found (Import-Module SqlServer failed, nothing under $ModuleRoot); install it with: Install-Module SqlServer -Scope CurrentUser" }
    Import-Module $cand[0].FullName -DisableNameChecking
}

function Get-AsPort([string]$instance) {
    # The service process of MSOLAP$<instance> is msmdsrv.exe; it listens on a dynamic port.
    $svc = Get-CimInstance Win32_Service -Filter ("Name='MSOLAP`${0}'" -f $instance) -ErrorAction SilentlyContinue
    $procId = $null
    if ($svc -and $svc.ProcessId) { $procId = $svc.ProcessId }
    else {
        $procs = @(Get-Process msmdsrv -ErrorAction SilentlyContinue)
        if ($procs.Count -eq 1) { $procId = $procs[0].Id }
    }
    if (-not $procId) { Fail "Analysis Services instance $instance is not running (no msmdsrv process)." }
    $listen = @(Get-NetTCPConnection -State Listen -OwningProcess $procId -ErrorAction SilentlyContinue |
                Select-Object -ExpandProperty LocalPort -Unique)
    if ($listen.Count -eq 0) { Fail "msmdsrv (PID $procId) has no listening TCP port." }
    return $listen[0]
}

function Assert-Response([string]$what, [string]$response) {
    # Errors come back inside the XMLA response as <Error ... Description="..."/> or <Exception/>.
    # Processing errors are often reported as <Warning> (the root cause) followed by generic <Error>s.
    $errors = [regex]::Matches($response, '<Error\b[^>]*?Description="([^"]*)"')
    $warnings = [regex]::Matches($response, '<Warning\b[^>]*?Description="([^"]*)"')
    foreach ($w in $warnings) { Say ('  warning: ' + [System.Net.WebUtility]::HtmlDecode($w.Groups[1].Value)) }
    if ($errors.Count -gt 0 -or $response -match '<Exception\b') {
        Say "FAILED: $what"
        foreach ($e in $errors) { Say ('  ' + [System.Net.WebUtility]::HtmlDecode($e.Groups[1].Value)) }
        if ($errors.Count -eq 0) { Say $response }
        exit 1
    }
    Say "OK: $what"
}

function Invoke-As([string]$what, [string]$query, [string]$db) {
    try {
        if ($db) { $r = Invoke-ASCmd -Server $script:Server -Database $db -Query $query }
        else     { $r = Invoke-ASCmd -Server $script:Server -Query $query }
    } catch {
        Fail "$what : $($_.Exception.Message)"
    }
    Assert-Response $what ([string]$r)
    return [string]$r
}

function Get-CellValues([string]$response) {
    # Returns the cell values (Value element, falling back to empty) in cell-ordinal order.
    $xml = [xml]$response
    $ns = New-Object System.Xml.XmlNamespaceManager($xml.NameTable)
    $ns.AddNamespace('md', 'urn:schemas-microsoft-com:xml-analysis:mddataset')
    $vals = @{}
    foreach ($c in $xml.SelectNodes('//md:CellData/md:Cell', $ns)) {
        $v = $c.SelectSingleNode('md:Value', $ns)
        $vals[[int]$c.CellOrdinal] = if ($v) { $v.InnerText } else { '' }
    }
    return $vals
}

Import-SqlServerModule
$port = Get-AsPort $Instance
$script:Server = "localhost:$port"
Say "Analysis Services instance $Instance at $($script:Server)"

if (-not $SmokeOnly) {
    if (-not (Test-Path $Xmla)) { Fail "XMLA file not found: $Xmla (run python tools\build_cube_xmla.py)" }
    $definition = [System.IO.File]::ReadAllText((Resolve-Path $Xmla), [System.Text.Encoding]::UTF8)
    $null = Invoke-As "create database $Database from $(Split-Path -Leaf $Xmla)" $definition $null
    $process = @"
<Process xmlns="http://schemas.microsoft.com/analysisservices/2003/engine">
  <Type>ProcessFull</Type>
  <Object><DatabaseID>$Database</DatabaseID></Object>
</Process>
"@
    $null = Invoke-As "process full $Database" $process $null
}

if ($Smoke -or $SmokeOnly) {
    $names = @('Segment Count', 'Stopover Segments', 'Total Price', 'Distinct Passengers', 'Average Price')
    $mdx = 'SELECT { [Measures].[Segment Count], [Measures].[Stopover Segments], [Measures].[Total Price], ' +
           '[Measures].[Distinct Passengers] } ON 0 FROM [FlightCube]'
    $vals = Get-CellValues (Invoke-As 'smoke query (totals)' $mdx $Database)
    $avg = Get-CellValues (Invoke-As 'smoke query (Average Price)' 'SELECT { [Measures].[Average Price] } ON 0 FROM [FlightCube]' $Database)
    $vals[4] = $avg[0]
    for ($i = 0; $i -lt $names.Count; $i++) {
        if (-not $vals.ContainsKey($i) -or $vals[$i] -eq '') { Fail "smoke query returned no value for $($names[$i])" }
        $inv = [System.Globalization.CultureInfo]::InvariantCulture
        $num = [double]::Parse($vals[$i], $inv)          # cell values may come as e.g. 2.3341E3
        Say ('SMOKE {0} = {1}' -f $names[$i], $num.ToString('0.######', $inv))
    }
}
exit 0
